class Producto:
    def __init__(self, nombre, precio, stock):
        self.nombre = nombre
        self.precio = precio
        self.stock = stock

    def precio_con_iva(self):
        return round(self.precio * 1.13)

    def hay_que_reponer(self, minimo=20):
        return self.stock < minimo

    def __str__(self):
        return f"{self.nombre}: ₡{self.precio:,}"

    def __repr__(self):
        return f"Producto({self.nombre!r}, {self.precio}, {self.stock})"

p = Producto("Hamaca de algodón", 32000, 10)
print(p.precio_con_iva())     # 36160
print(p.hay_que_reponer())    # True
print(p)                      # Hamaca de algodón: ₡32,000
print([p])                    # [Producto('Hamaca de algodón', 32000, 10)]

class Producto:
    def __init__(self, nombre, stock):
        self.nombre = nombre
        self._stock = 0
        self.stock = stock            # pasa por el setter: se valida

    @property
    def stock(self):
        return self._stock

    @stock.setter
    def stock(self, nuevo):
        if nuevo < 0:
            raise ValueError("el stock no puede ser negativo")
        self._stock = nuevo

    def vender(self, cantidad):
        self.stock = self.stock - cantidad

bolso = Producto("Bolso de manta", 3)
bolso.vender(2)
print(bolso.stock)                # 1
try:
    bolso.vender(5)
except ValueError as e:
    print("Error:", e)            # Error: el stock no puede ser negativo
print(bolso.stock)                # 1

class LineaPedido:
    def __init__(self, producto, cantidad, precio_unitario, descuento=0):
        self.producto = producto
        self.cantidad = cantidad
        self.precio_unitario = precio_unitario
        self.descuento = descuento

    def total(self):
        return self.cantidad * self.precio_unitario * (1 - self.descuento)

class Pedido:
    creados = 0                       # atributo de clase: compartido

    def __init__(self, id, cliente_id):
        self.id = id
        self.cliente_id = cliente_id
        self.lineas = []              # composición: una lista de LineaPedido
        Pedido.creados += 1

    def agregar(self, linea):
        self.lineas.append(linea)

    def total(self):
        return sum(linea.total() for linea in self.lineas)

    @classmethod
    def desde_tuplas(cls, id, cliente_id, filas):
        pedido = cls(id, cliente_id)
        for producto, cantidad, precio, descuento in filas:
            pedido.agregar(LineaPedido(producto, cantidad, precio, descuento))
        return pedido

