class Empleado:
    def __init__(self, nombre, salario):
        self.nombre = nombre
        self.salario = salario

    def pago_mensual(self):
        return self.salario

    def __str__(self):
        return f"{type(self).__name__} {self.nombre}"

class Vendedor(Empleado):
    def __init__(self, nombre, salario, ventas_mes):
        super().__init__(nombre, salario)
        self.ventas_mes = ventas_mes

    def pago_mensual(self):
        # salario base más 2 % de comisión sobre lo vendido en el mes
        return super().pago_mensual() + round(self.ventas_mes * 0.02)

ana = Empleado("Ana Lucía", 1380000)
felipe = Vendedor("Felipe", 780000, 1500000)
print(ana, ana.pago_mensual())                              # Empleado Ana Lucía 1380000
print(felipe, felipe.pago_mensual())                        # Vendedor Felipe 810000
print(isinstance(felipe, Empleado), isinstance(ana, Vendedor))  # True False

from abc import ABC, abstractmethod

class Envio(ABC):
    @abstractmethod
    def costo(self, total):
        ...

class RetiroEnTienda(Envio):
    def costo(self, total):
        return 0

class Mensajeria(Envio):
    def __init__(self, tarifa):
        self.tarifa = tarifa

    def costo(self, total):
        return 0 if total >= 50000 else self.tarifa   # gratis desde ₡50000

envios = [RetiroEnTienda(), Mensajeria(2500), Mensajeria(3500)]
for envio in envios:
    print(type(envio).__name__, envio.costo(32000))
# RetiroEnTienda 0
# Mensajeria 2500
# Mensajeria 3500
print(sum(envio.costo(60000) for envio in envios))   # 0
